 if(!r.providers.length)return void b.append(headBar('Limpador de Disco na Nuvem'),emptyBox('\uf0c2','Nenhuma pasta de nuvem encontrada','Instale e entre no OneDrive, Google Drive, Dropbox, iCloud ou Box neste computador.',h('button',{class:'cc-pill',disabled:!can(),onclick:scan},'Escanear novamente')));
