  items.length?h('table',{class:'cc-tbl'},h('thead',{},h('tr',{},h('th',{style:'width:30px'},tri(h('input',{type:'checkbox','aria-label':'Selecionar todos',onchange:e=>{e.target.checked?items.forEach(i=>cloudSel.add(i.id)):items.forEach(i=>cloudSel.delete(i.id));render()}}),items.map(i=>i.id),cloudSel)),h('th',{},'Arquivo'),h('th',{},'Conta'),h('th',{},'Modificado'),h('th',{class:'n'},'Tamanho'))),h('tbody',{},items.map(i=>h('tr',{},h('td',{},h('input',{type:'checkbox','aria-label':'Selecionar arquivo',checked:cloudSel.has(i.id),onchange:e=>{e.target.checked?cloudSel.add(i.id):cloudSel.delete(i.id);render()}})),h('td',{style:'word-break:break-all'},i.path,i.local?null:h('small',{class:'mut'},' · somente na nuvem')),h('td',{class:'mut'},CPROV[i.provider]||i.provider),h('td',{class:'mut'},i.modified?new Date(i.modified*1000).toLocaleDateString('pt-BR'):'—'),h('td',{class:'n'},size(i.bytes))))))
  :h('p',{class:'mut',style:'padding:14px 0'},'Nada encontrado nesta categoria.')));
